kerf-recipe 1
render court {depth.mp4} pass=depth size=832x480 rate=16
render court {matte.mp4} matte=ball from=1 seconds=2
generate model=still prompt="an orange basketball, studio light" seed=3 out={ball.png}
generate model=video prompt="a basketball bounces on a court" guide={depth.mp4} guide_ids={matte.mp4} ref={ball.png} ref=refs/there.png ref=refs/gone.png cast=Ada cast=Nobody style=film signal=bounce signal=nosuch moves=ball moves=nomove from=0.5 seconds=4 size=832x480 seed=7 strength=0.8 out={a.mp4}
generate model=video prompt="it goes on" first={a.mp4} out={b.mp4}
join {a.mp4} {b.mp4} {out} lap=1
